/**
 * The downloaded PDF must not contain literal markdown markers (**bold**). jsPDF writes
 * text uncompressed by default, so we can read the generated bytes and assert the clause
 * sub-headings render as words, not "**Survivorship**".
 *
 * Run:  npx vitest run src/lib/pdf/__tests__/renderWillPdf.format.test.ts
 */
import { describe, it, expect } from 'vitest'
import { renderWillPdf } from '../renderWillPdf'

const SAMPLE = [
  'LAST WILL AND TESTAMENT OF JANE SMITH',
  '',
  'I, Jane Smith, of 1 Test St, declare this to be my Last Will and Testament.',
  '',
  '7. SURVIVORSHIP AND GIFT RULES',
  '',
  '**Survivorship**',
  '',
  'A beneficiary must survive me by at least 30 days to be entitled to receive a gift.',
  '',
  'Effect of marriage and divorce',
  '',
  'If I marry or divorce after signing this Will, the law applying to my estate determines the effect.',
  '',
  'IN WITNESS WHEREOF I have set my hand to this my Will.',
].join('\n')

describe('renderWillPdf — no literal markdown in the PDF text', () => {
  it('strips ** from the generated PDF stream while keeping the words', async () => {
    const bytes = await renderWillPdf(SAMPLE)
    const pdf = Buffer.from(bytes as ArrayBuffer).toString('latin1')
    expect(pdf).not.toContain('**') // no literal bold markers
    expect(pdf).toContain('Survivorship') // the sub-heading still renders as a word
  })
})
